    "landlab.components.network_sediment_transporter.sediment_pulser_at_links",
    "landlab.components.network_sediment_transporter.sediment_pulser_each_parcel",
    "landlab.data_record.data_record",
    "landlab.data_record.aggregators",
]
out = {}
for name in mods:
    try:
        m = importlib.import_module(name)
    except Exception as exc:
        out[name] = {"import_error": repr(exc)}
        continue
    runner = doctest.DocTestRunner(optionflags=doctest.NORMALIZE_WHITESPACE | doctest.ELLIPSIS, verbose=False)
    finder = doctest.DocTestFinder()
    fails = []
    for test in finder.find(m, name, globs=None):
        buf = io.StringIO()
        res = runner.run(test, out=buf.write, clear_globs=True)
        if res.failed:
            fails.append({"name": test.name, "failed": res.failed, "attempted": res.attempted, "log": buf.getvalue()})
    out[name] = {"failures": fails, "n_fail": sum(f["failed"] for f in fails)}
json.dump(out, open(f"/tmp/doctests_{mode}.json", "w"), indent=1)
for k, v in out.items():
    print(k, v.get("n_fail", v))
